RSpec.describe Invoices::OutboxDelivery, "stale_generation answers delivered twice" do
  let(:stale_twice_fake) { TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key) }
  let(:stale_twice_client) { Timekeeping::ReservationClient.new(http: TimekeepingContract::FakeClient.new(timekeeping: stale_twice_fake, relay: nil)) }

  around do |example|
    with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV => timekeeping_key_pair.to_pem) { example.run }
  end

  # Delivered twice: inline delivery and the recovery sweep can both reach one stale row.
  it "timekeeping client: delivering a stale_generation commit row twice marks it undeliverable once, emits one event and sends nothing the second time" do
    company_id = stale_twice_fake.add_company
    user_id = stale_twice_fake.add_user(company_id:, role: "admin")
    entry_id = stale_twice_fake.add_entry(company_id:, user_id:, project_id: stale_twice_fake.add_project(company_id:))["id"]
    operation_id = SecureRandom.uuid
    generation = stale_twice_fake.generation
    request = Invoices::ReservationRequest.new(
      company_id:, invoice_id: 8301, operation_id:, generation:, disposition: "active", entries: [entry_id]
    )
    expect(stale_twice_client.prepare(request).state).to eq("prepared")
    InvoiceOperationIntent.create!(
      company_id:, invoice_id: 8301, operation_id:, state: "committed", generation:,
      disposition: "active", desired_entry_ids: [entry_id]
    )
    row = InvoiceOperationOutboxItem.create!(
      company_id:, invoice_id: 8301, operation_id:, kind: "commit",
      payload: { company_id:, invoice_id: 8301, operation_id:, generation:, disposition: "active", desired_entry_ids: [entry_id] }
    )
    stale_twice_fake.generation = generation + 1
    delivery = described_class.new(adapter_source: -> { stale_twice_client })

    events = []
    subscriber = Object.new
    subscriber.define_singleton_method(:emit) { |event| events << event }
    Rails.event.subscribe(subscriber)
    begin
      delivery.deliver(row.id)
      first_marked_at = row.reload.undeliverable_at
      requests_after_first = stale_twice_fake.requests.size
      travel 1.minute do
        delivery.deliver(row.id)
      end
    ensure
      Rails.event.unsubscribe(subscriber)
    end
    payloads = events.filter_map do |event|
      event[:payload].to_h.symbolize_keys if event[:name] == Invoices::UndeliverableOperation::NAME
    end

    # "`stale_generation` marks the row undeliverable with a log signal."
    expect(first_marked_at).to be_present
    expect(InvoiceOperationOutboxItem.exists?(row.id)).to be(true)
    expect(row.reload.delivered_at).to be_nil
    expect(row.undeliverable_at).to eq(first_marked_at)
    # "a stale_generation answer sets `undeliverable_at`, keeps the row and emits one event, and a later recovery run sends no request for that row."
    expect(payloads).to eq([{ company_id:, operation_id:, kind: "commit" }])
    # "`OutboxDelivery#deliver` and `RecoverInvoiceOperationIntentsJob#deliver_undelivered` skip rows that have `undeliverable_at` set."
    expect(stale_twice_fake.requests.size).to eq(requests_after_first)
    expect(Invoices::UndeliverableOperation::NAME).to eq("invoices.undeliverable_operation")
  end
end

