RSpec.describe Invoices::OutboxDelivery, "a lost commit answer" do
  let(:lost_commit_fake) { TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key) }

  around do |example|
    with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV => timekeeping_key_pair.to_pem) { example.run }
  end

  # Partial failure: the fake applies the first commit, then the answer is dropped on the way back.
  # A lost answer carries no reason, so it must stay an ordinary retry, never an undeliverable row.
  it "timekeeping client: a commit the fake applied but whose answer was lost is not marked undeliverable, and redelivery settles it without applying it again" do
    dropping_first_commit = Class.new do
      def initialize(inner)
        @inner = inner
        @dropped = false
      end

      def call(method, path, headers: {}, body: nil)
        answer = @inner.call(method, path, headers:, body:)
        if !@dropped && path.end_with?("/reservations/commit")
          @dropped = true
          raise Timekeeping::ReservationHttp::Error, "answer lost after the fake applied the commit"
        end
        answer
      end
    end
    client = Timekeeping::ReservationClient.new(
      http: dropping_first_commit.new(TimekeepingContract::FakeClient.new(timekeeping: lost_commit_fake, relay: nil))
    )
    company_id = lost_commit_fake.add_company
    user_id = lost_commit_fake.add_user(company_id:, role: "admin")
    entry_id = lost_commit_fake.add_entry(company_id:, user_id:, project_id: lost_commit_fake.add_project(company_id:))["id"]
    operation_id = SecureRandom.uuid
    generation = lost_commit_fake.generation
    request = Invoices::ReservationRequest.new(
      company_id:, invoice_id: 8401, operation_id:, generation:, disposition: "active", entries: [entry_id]
    )
    expect(client.prepare(request).state).to eq("prepared")
    InvoiceOperationIntent.create!(
      company_id:, invoice_id: 8401, operation_id:, state: "committed", generation:,
      disposition: "active", desired_entry_ids: [entry_id]
    )
    row = InvoiceOperationOutboxItem.create!(
      company_id:, invoice_id: 8401, operation_id:, kind: "commit",
      payload: { company_id:, invoice_id: 8401, operation_id:, generation:, disposition: "active", desired_entry_ids: [entry_id] }
    )
    delivery = described_class.new(adapter_source: -> { client })

    delivery.deliver(row.id)

    # The fake really applied the dropped commit.
    applied_once = lost_commit_fake.reservations_for(entry_id)
    expect(applied_once).to eq([{ "invoice_id" => 8401, "state" => "committed" }])
    expect(row.reload.delivered_at).to be_nil
    expect(row.undeliverable_at).to be_nil
    expect(row.attempts).to eq(1)

    delivery.deliver(row.id)

    # "A lost commit answer is redelivered and applies once"
    expect(row.reload.delivered_at).to be_present
    expect(row.undeliverable_at).to be_nil
    expect(lost_commit_fake.reservations_for(entry_id)).to eq(applied_once)
    expect(lost_commit_fake.entry_locked?(entry_id)).to be(true)
    commit_bodies = lost_commit_fake.requests.filter_map do |logged|
      logged[:body] if logged[:path].end_with?("/reservations/commit")
    end
    expect(commit_bodies.size).to eq(2)
    expect(commit_bodies.uniq.size).to eq(1)
  end
end

